def redundant_undirected_edge(edges):
    parent=list(range(len(edges)+1))
    def find(x):
        while parent[x]!=x:
            parent[x]=parent[parent[x]];x=parent[x]
        return x
    for left,right in edges:
        a,b=find(left),find(right)
        if a==b:return [left,right]
        parent[a]=b

